import re
from dataclasses import dataclass
from datetime import datetime

LINE_RE = re.compile(
    r'(?P<ip>\S+) \S+ \S+ \[(?P<time>[^\]]+)\] '
    r'"(?P<method>[A-Z]+) (?P<path>\S+) [^"]*" '
    r'(?P<status>\d{3}) (?P<size>\d+|-) (?P<rt>\d+(?:\.\d+)?)'
)
TIME_FORMAT = "%d/%b/%Y:%H:%M:%S %z"


@dataclass(frozen=True)
class Entry:
    ip: str
    time: datetime
    method: str
    path: str
    status: int
    size: int
    response_time: float

    @property
    def is_error(self):
        return self.status >= 500

    @property
    def is_client_error(self):
        return 400 <= self.status < 500


def parse_line(line):
    match = LINE_RE.match(line.strip())
    if match is None:
        return None
    try:
        when = datetime.strptime(match["time"], TIME_FORMAT)
    except ValueError:
        return None
    size = 0 if match["size"] == "-" else int(match["size"])
    return Entry(
        ip=match["ip"],
        time=when,
        method=match["method"],
        path=match["path"].split("?")[0],
        status=int(match["status"]),
        size=size,
        response_time=float(match["rt"]),
    )


def parse_lines(lines):
    """Return (entries, malformed_count)."""
    entries = []
    bad = 0
    for line in lines:
        if not line.strip():
            continue
        entry = parse_line(line)
        if entry is None:
            bad += 1
        else:
            entries.append(entry)
    return entries, bad


def parse_file(path):
    with open(path, encoding="utf-8", errors="replace") as handle:
        return parse_lines(handle)

import unittest

from loglens.parser import parse_line, parse_lines

GOOD = '10.0.0.5 - - [01/Oct/2026:08:00:17 +0000] "GET /login?next=/home HTTP/1.1" 200 512 0.125'


class ParserTests(unittest.TestCase):
    def test_parses_fields(self):
        entry = parse_line(GOOD)
        self.assertEqual(entry.ip, "10.0.0.5")
        self.assertEqual(entry.method, "GET")
        self.assertEqual(entry.status, 200)
        self.assertEqual(entry.size, 512)
        self.assertAlmostEqual(entry.response_time, 0.125)

    def test_query_string_is_dropped(self):
        self.assertEqual(parse_line(GOOD).path, "/login")

    def test_dash_size_means_zero(self):
        line = GOOD.replace(" 512 ", " - ")
        self.assertEqual(parse_line(line).size, 0)

    def test_garbage_returns_none(self):
        self.assertIsNone(parse_line("not a log line"))

    def test_bad_date_returns_none(self):
        self.assertIsNone(parse_line(GOOD.replace("Oct", "Foo")))

    def test_counts_malformed_lines(self):
        entries, bad = parse_lines([GOOD, "junk", "", GOOD])
        self.assertEqual((len(entries), bad), (2, 1))

    def test_error_flags(self):
        entry = parse_line(GOOD.replace(" 200 ", " 503 "))
        self.assertTrue(entry.is_error)
        self.assertFalse(entry.is_client_error)


if __name__ == "__main__":
    unittest.main()

from collections import Counter


def top_n(entries, key, n=5):
    counts = Counter(getattr(e, key) for e in entries)
    ranked = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return ranked[:n]


def status_classes(entries):
    counts = Counter(f"{e.status // 100}xx" for e in entries)
    return dict(sorted(counts.items()))


def error_rate(entries):
    if not entries:
        return 0.0
    return sum(1 for e in entries if e.is_error) / len(entries)


def timeline(entries, bucket="hour"):
    fmt = {"hour": "%Y-%m-%d %H:00", "minute": "%Y-%m-%d %H:%M", "day": "%Y-%m-%d"}[bucket]
    counts = Counter(e.time.strftime(fmt) for e in entries)
    return sorted(counts.items())


def slowest(entries, n=5):
    return sorted(entries, key=lambda e: e.response_time, reverse=True)[:n]


def summarize(entries):
    times = [e.response_time for e in entries]
    return {
        "requests": len(entries),
        "unique_ips": len({e.ip for e in entries}),
        "bytes": sum(e.size for e in entries),
        "error_rate": round(error_rate(entries), 4),
        "status": status_classes(entries),
        "avg_ms": round(1000 * sum(times) / len(times), 1) if times else 0.0,
        "p50_ms": round(1000 * percentile(times, 50), 1),
        "p95_ms": round(1000 * percentile(times, 95), 1),
        "top_paths": top_n(entries, "path", 3),
    }


def percentile(values, pct):
    if not values:
        return 0.0
    ordered = sorted(values)
    rank = len(ordered) * pct / 100
    low = int(rank)
    high = min(low + 1, len(ordered) - 1)
    return ordered[low] + (ordered[high] - ordered[low]) * (rank - low)

import unittest
from datetime import datetime, timezone

from loglens.parser import Entry
from loglens.stats import percentile, summarize, timeline, top_n


def make(path="/", status=200, minute=0, ip="1.1.1.1", rt=0.1, hour=8):
    when = datetime(2026, 10, 1, hour, minute, tzinfo=timezone.utc)
    return Entry(ip, when, "GET", path, status, 100, rt)


class StatsTests(unittest.TestCase):
    def test_percentile_median(self):
        self.assertEqual(percentile([1, 2, 3, 4, 5], 50), 3)

    def test_percentile_interpolates(self):
        self.assertEqual(percentile([1, 2, 3, 4], 50), 2.5)

    def test_percentile_extremes(self):
        self.assertEqual(percentile([4, 1, 3], 0), 1)
        self.assertEqual(percentile([4, 1, 3], 100), 4)

    def test_percentile_empty(self):
        self.assertEqual(percentile([], 95), 0.0)

    def test_top_n_orders_by_count_then_name(self):
        entries = [make("/b"), make("/a"), make("/b"), make("/c")]
        self.assertEqual(top_n(entries, "path", 2), [("/b", 2), ("/a", 1)])

    def test_summary_numbers(self):
        entries = [make(status=200), make(status=500, ip="2.2.2.2"), make(status=404)]
        s = summarize(entries)
        self.assertEqual(s["requests"], 3)
        self.assertEqual(s["unique_ips"], 2)
        self.assertEqual(s["status"], {"2xx": 1, "4xx": 1, "5xx": 1})
        self.assertAlmostEqual(s["error_rate"], 0.3333, places=4)

    def test_summary_of_nothing(self):
        self.assertEqual(summarize([])["requests"], 0)

    def test_timeline_buckets_by_hour(self):
        entries = [make(hour=8, minute=1), make(hour=8, minute=50), make(hour=9)]
        self.assertEqual(
            timeline(entries, "hour"),
            [("2026-10-01 08:00", 2), ("2026-10-01 09:00", 1)],
        )


if __name__ == "__main__":
    unittest.main()

