import csv
import io
import json


def format_table(rows, headers):
    table = [list(map(str, headers))] + [[str(c) for c in row] for row in rows]
    widths = [max(len(r[i]) for r in table) for i in range(len(headers))]
    lines = []
    for n, row in enumerate(table):
        lines.append("  ".join(cell.ljust(widths[i]) for i, cell in enumerate(row)).rstrip())
        if n == 0:
            lines.append("  ".join("-" * w for w in widths))
    return "\n".join(lines)


def to_csv(rows, headers):
    buf = io.StringIO()
    writer = csv.writer(buf, lineterminator="\n")
    writer.writerow(headers)
    writer.writerows(rows)
    return buf.getvalue()


def render_summary(stats, malformed=0, fmt="text"):
    if fmt == "json":
        return json.dumps({**stats, "malformed_lines": malformed}, indent=2)
    lines = [
        f"Requests:      {stats['requests']}",
        f"Unique IPs:    {stats['unique_ips']}",
        f"Bytes sent:    {stats['bytes']}",
        f"Error rate:    {stats['error_rate']:.1f}%",
        f"Latency (ms):  avg {stats['avg_ms']}  p50 {stats['p50_ms']}  p95 {stats['p95_ms']}",
        "Status:        " + ", ".join(f"{k}={v}" for k, v in stats["status"].items()),
    ]
    if malformed:
        lines.append(f"Malformed:     {malformed} line(s) skipped")
    return "\n".join(lines)

